def solve_nqueens():
    n = 9
    fixed = {3: 1}  # q[3] = 1

    solution = []

    def is_safe(placement, row, col):
        for r, c in enumerate(placement):
            if c == col:
                return False
            if abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(row, placement):
        if row == n:
            return placement[:]

        # If this row has a fixed value, try only that
        if row in fixed:
            col = fixed[row]
            if is_safe(placement, row, col):
                placement.append(col)
                result = backtrack(row + 1, placement)
                if result:
                    return result
                placement.pop()
            return None

        for col in range(n):
            if is_safe(placement, row, col):
                placement.append(col)
                result = backtrack(row + 1, placement)
                if result:
                    return result
                placement.pop()
        return None

    result = backtrack(0, [])
    return result

solution = solve_nqueens()
print("Solution:", solution)

if solution:
    # Verify
    n = 9
    print("\nBoard visualization:")
    for r in range(n):
        row_str = ""
        for c in range(n):
            row_str += "Q " if solution[r] == c else ". "
        print(f"Row {r}: {row_str}  (col={solution[r]})")

    # Check constraints
    print("\nVerification:")
    print(f"q[3] = {solution[3]} (should be 1): {'✓' if solution[3]==1 else '✗'}")

    valid = True
    for i in range(n):
        for j in range(i+1, n):
            if solution[i] == solution[j]:
                print(f"CONFLICT: rows {i},{j} same column")
                valid = False
            if abs(i-j) == abs(solution[i]-solution[j]):
                print(f"CONFLICT: rows {i},{j} on diagonal")
                valid = False
    print(f"All constraints satisfied: {'✓' if valid else '✗'}")
